Chest.css:
body{margin:0;font-family:'Baloo 2',-apple-system,BlinkMacSystemFont,'PingFang SC','Hiragino Sans GB','Microsoft YaHei','HarmonyOS Sans SC','MiSans',system-ui,sans-serif;background:#F7F2EB;color:#261408}
a{color:#A8430B;text-decoration:none}a:hover{color:#7E3208}
button,a{transition:transform .12s ease,box-shadow .15s ease,filter .15s ease,background-color .15s ease}button:not(:disabled):hover,a:hover{filter:brightness(1.04)}button:not(:disabled):active,a:active{transform:translateY(1px) scale(.99);filter:brightness(.97)}button:focus-visible,a:focus-visible{outline:3px solid #6C63FF;outline-offset:3px}
h1,h2,h3{line-height:1.25;letter-spacing:-0.01em;text-wrap:balance}p{line-height:1.6}
body{-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;font-variant-numeric:tabular-nums}
@keyframes pp-spin{to{transform:rotate(360deg)}}
.pp-rays{animation:pp-spin 18s linear infinite}
@keyframes pp-shake{0%,100%{transform:rotate(0)}20%{transform:rotate(-6deg)}40%{transform:rotate(5deg)}60%{transform:rotate(-3deg)}80%{transform:rotate(2deg)}}
.pp-shake{animation:pp-shake 1.2s ease-in-out infinite;transform-origin:50% 90%}
@keyframes pp-popin{0%{transform:scale(.4);opacity:0}60%{transform:scale(1.12);opacity:1}100%{transform:scale(1)}}
.pp-popin{animation:pp-popin .6s cubic-bezier(.3,1.4,.5,1) both}
@keyframes pp-burst{from{transform:translate(0,0) scale(.2);opacity:0}to{transform:translate(var(--dx),var(--dy)) scale(1);opacity:1}}
.pp-burst{animation:pp-burst .7s cubic-bezier(.2,.9,.3,1.2) both}
@keyframes pp-fall{0%{transform:translateY(-30px) rotate(0);opacity:0}20%{opacity:1}100%{transform:translateY(40px) rotate(160deg);opacity:0}}
.pp-conf{animation:pp-fall 2.6s ease-in infinite}
@keyframes pp-flick{0%,100%{transform:scale(1) rotate(0)}30%{transform:scale(.94,1.04) rotate(-2deg)}60%{transform:scale(1.03,.97) rotate(2deg)}}
.pp-flick{animation:pp-flick 1.4s ease-in-out infinite;transform-origin:50% 100%}
@keyframes pp-bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}
.pp-bob{animation:pp-bob 3.2s ease-in-out infinite}
@keyframes pp-rise{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
.pp-rise{animation:pp-rise .45s ease-out both}
@keyframes pp-toast{from{opacity:0;transform:translate(-50%,8px)}to{opacity:1;transform:translate(-50%,0)}}
@media (prefers-reduced-motion:reduce){.pp-rays,.pp-shake,.pp-popin,.pp-burst,.pp-conf,.pp-flick,.pp-bob,.pp-rise{animation:none}}
/*pp-glassbtn*/a[style*="inset 0 -2px 0 rgba(0,0,0,.06)"]:active,button[style*="inset 0 -2px 0 rgba(0,0,0,.06)"]:not(:disabled):active{transform:scale(.97)!important;filter:brightness(.95)!important}

